CREATE OR REPLACE FUNCTION public.icash_apply_prepaid_purchase(p_order uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.icash_funding_orders;funded bigint;a public.icash_accounts;
begin
 select * into o from public.icash_funding_orders where id=p_order for update;
 if not found or o.mode<>'live' or o.state<>'paid' or o.account_id is null or o.credited_at is null then return false;end if;
 if o.prepaid_applied_at is not null then return true;end if;
 if not exists(select 1 from public.icash_funding_consents c where c.order_id=o.id and c.version in ('work-credits-2026-10-03.1','work-credits-2026-10-05.1','work-credits-2026-10-06.1','work-credits-2026-10-06.1:recharge-2026-10-06.1','work-credits-2026-10-07.1','work-credits-2026-10-07.1:recharge-2026-10-06.1','work-credits-2026-10-10.1','work-credits-2026-10-10.1:recharge-2026-10-10.1','work-credits-2026-10-20.1:recharge-2026-10-10.1','work-credits-2026-10-20.1') and c.account_id=o.account_id and c.price_cents=o.price_cents and c.credit_cents=o.credit_cents) then return false;end if;
 select * into a from public.icash_accounts where id=o.account_id for update;
 if exists(select 1 from public.icash_daily_plans where account_id=a.id and mode='live' and state<>'stopped') then return false;end if;
 if exists(select 1 from public.icash_billing_reviews where account_id=a.id and resolved_at is null) or not public.icash_membership_work_allowed(a.id) then return false;end if;
 perform 1 from public.icash_wallets where account_id=a.id for update;
 select coalesce(sum(credit_cents),0)+public.icash_authorized_grant_cents(a.id) into funded from public.icash_funding_orders where account_id=a.id and mode='live' and state='paid' and credited_at is not null;
 if funded<=0 or funded>100000000 then return false;end if;
 insert into public.icash_spend_activations(account_id,enabled,customer_cap_cents) values(a.id,true,funded)
 on conflict(account_id) do update set enabled=true,customer_cap_cents=excluded.customer_cap_cents;
 update public.icash_accounts set billing_model=case when billing_model='legacy' then 'prepaid' else billing_model end,daily_limit_cents=(select reserved_cents+public.icash_credit_work_pace(greatest(0,balance_cents-reserved_cents))+coalesce((select sum(-delta_cents) from public.icash_credit_ledger where account_id=a.id and kind='usage' and created_at>now()-interval '24 hours'),0) from public.icash_wallets where account_id=a.id),bot_paused=false where id=a.id;
 update public.icash_funding_orders set prepaid_applied_at=now(),pacing_applied_at=now() where id=o.id;
 -- Provider/channel, identity, contact, cost, offer and contract authority checks still run at dispatch.
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prospecting_progress(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare b public.icash_prospecting_budgets;remaining bigint;total_remaining bigint;minimum bigint;spent bigint;pending bigint;queued bigint;screened bigint;eligible bigint;attempted bigint;responded bigint;active boolean;paused boolean;
begin
 select * into b from public.icash_prospecting_budgets where account_id=p_account order by id desc limit 1;
 if not found then return null;end if;
 remaining:=public.icash_prospecting_available(p_account);
 total_remaining:=public.icash_prospecting_total_available(p_account);
 select least(search.charge_cents,contacts.charge_cents) into minimum from public.icash_discovery_configs c join public.icash_operation_rates search on search.id=c.rate_id left join public.icash_operation_rates contacts on contacts.id=c.contact_rate_id where c.account_id=p_account;
 select coalesce(sum(charged_cents) filter(where state='settled'),0),coalesce(sum(charge_cap_cents) filter(where state in ('reserved','dispatched')),0) into spent,pending from public.icash_operation_spend where account_id=p_account and prospecting_budget_id=b.id;
 select bot_paused into paused from public.icash_accounts where id=p_account;
 select count(*) filter(where s.state in ('queued','running')),count(*) filter(where s.state='complete'),count(*) filter(where s.state='complete' and s.result->'financialCheck'->>'status'='eligible')
  into queued,screened,eligible from public.icash_screening_jobs s where s.account_id=p_account and s.created_at>=b.created_at and s.state<>'archived';
 select count(*) filter(where o.attempted),count(*) filter(where o.responded and not o.opted_out) into attempted,responded
  from public.icash_opportunity_outcomes o where o.account_id=p_account and o.discovered_at>=b.created_at;
 active:=exists(select 1 from public.icash_automation_tickets where account_id=p_account and kind in ('discovery','contacts','voice_dispatch','seller_opener') and state='consumed' and created_at>now()-interval '2 minutes') or queued>0;
 return jsonb_build_object('budgetId',b.id,'startedAt',b.created_at,'limitCents',b.limit_cents,'pacingHours',24,'dailyPercent',25,'dailyLimitCents',b.baseline_cents/4,'batchHours',1,'hourlyLimitCents',least(b.baseline_cents/4,greatest(500,ceil(b.limit_cents/10.0))),'releasedCents',public.icash_prospecting_released(b.baseline_cents,b.created_at),'spentCents',spent,'pendingCents',pending,'remainingCents',remaining,
  'queued',queued,'screened',screened,'eligible',eligible,'contacted',attempted,'responded',responded,
  'status',case when paused then 'paused' when not public.icash_membership_work_allowed(p_account) then 'membership_required'
   when remaining<coalesce(minimum,1) and pending>0 then 'settling' when remaining<coalesce(minimum,1) and total_remaining>=coalesce(minimum,1) then 'paced' when remaining<coalesce(minimum,1) then 'budget_reached' when active then 'working'
   when exists(select 1 from public.icash_discovery_configs where account_id=p_account and enabled and auto_enabled and data_rights_until>now()) then 'ready' else 'waiting' end);
end $function$
